17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.UUID;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Syntactic email validation: a non-empty local part, a single '@', and a
62	     * domain with at least one dot-separated label ending in a letter-only TLD.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    /**
86	     * Normalise a raw telephone number to E.164 form.
87	     *
88	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
89	     * code are kept when present; otherwise country code '+61' is assumed and a
90	     * single leading '0' is dropped from the national digits. The result must have
91	     * between 8 and 15 digits after the '+'.
92	     *
93	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
94	     */
95	    static String toE164(String raw) {
96	        if (raw == null) {
97	            return null;
98	        }
99	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
100	        String digits;
101	        if (cleaned.startsWith("+")) {
102	            digits = cleaned.substring(1);
103	        } else {
104	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
105	            digits = "61" + national;
106	        }
107	        if (!digits.matches("[0-9]{8,15}")) {
108	            return null;
109	        }
110	        return "+" + digits;
111	    }
112	
113	    /**
114	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
115	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
116	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
117	     * input normalises to the empty string.
118	     */
119	    private static String normaliseIdentity(String value) {
120	        if (value == null) {
121	            return "";
122	        }
123	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
124	    }
125	
126	    /**
127	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
128	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
129	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
130	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
131	     * that is both stored and used for every address comparison.
132	     */
133	    static String normaliseAddress(String value) {
134	        if (value == null) {
135	            return "";
136	        }
137	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
138	        if (collapsed.isEmpty()) {
139	            return "";
140	        }
141	        String[] tokens = collapsed.split(" ");
142	        StringBuilder result = new StringBuilder();
143	        for (int i = 0; i < tokens.length; i++) {
144	            if (i > 0) {
145	                result.append(' ');
146	            }
147	            result.append(expandAddressAbbreviation(tokens[i]));
148	        }
149	        return result.toString();
150	    }
151	
152	    /**
153	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
154	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
155	     * returned unchanged.
156	     */
157	    private static String expandAddressAbbreviation(String token) {
158	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
159	        return switch (core) {
160	            case "ST" -> "STREET";
161	            case "RD" -> "ROAD";
162	            case "AVE" -> "AVENUE";
163	            default -> token;
164	        };
165	    }
166	
167	    /**
168	     * Derive the stable, shared household identifier for owners sharing a household. It is a
169	     * deterministic UUID over the normalised last-name and address, so every owner in the same
170	     * household resolves to the same value regardless of the order in which they were created.
171	     */
172	    private static String householdId(String lastNameKey, String addressKey) {
173	        String seed = lastNameKey + "�" + addressKey;
174	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
175	    }
176	
177	    /**
178	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
179	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
180	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
181	     * owners already in that city at the time the owner was created.
182	     */
183	    private String nextCustomerCode(String city, String lastName) {
184	        String city3 = prefix3(city);
185	        String last3 = prefix3(lastName);
186	        String cityKey = normaliseIdentity(city);
187	        int sequence = (int) this.clinicService.findAllOwners().stream()
188	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
189	            .count() + 1;
190	        return String.format("%s-%s-%04d", city3, last3, sequence);
191	    }
192	
193	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
194	    private static String prefix3(String value) {
195	        String letters = value == null ? "" : value;
196	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
202	        Collection<Owner> owners;
203	        if (lastName != null) {
204	            owners = this.clinicService.findOwnerByLastName(lastName);
205	        } else {
206	            owners = this.clinicService.findAllOwners();
207	        }
208	        if (owners.isEmpty()) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner == null) {
219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
227	        String telephone = toE164(ownerFieldsDto.getTelephone());
228	        if (telephone == null) {
229	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
230	        }
231	        String email = ownerFieldsDto.getEmail();
232	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
233	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
234	        }
235	        String address = normaliseAddress(ownerFieldsDto.getAddress());
236	        if (address.isEmpty()) {
237	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
238	        }
239	        LocalDate today = LocalDate.now();
240	        long ownersCreatedToday = this.clinicService.findAllOwners().stream()
241	            .filter(existing -> today.equals(existing.getRegistrationDate()))
242	            .count();
243	        if (ownersCreatedToday >= 100) {
244	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
245	        }
246	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
247	        long ownersInCity = this.clinicService.findAllOwners().stream()
248	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
249	            .count();
250	        if (ownersInCity >= 50) {
251	            return new ResponseEntity<>(HttpStatus.CONFLICT);
252	        }
253	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
254	            .map(Owner::getTelephone)
255	            .map(OwnerRestControllerV1::toE164)
256	            .filter(existing -> existing != null)
257	            .anyMatch(telephone::equals);
258	        if (telephoneInUse) {
259	            return new ResponseEntity<>(HttpStatus.CONFLICT);
260	        }
261	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
262	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
263	        String addressKey = address;
264	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
265	            .filter(existing ->
266	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
267	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
268	            .toList();
269	        if (!householdMembers.isEmpty() && !sharesHousehold) {
270	            return new ResponseEntity<>(HttpStatus.CONFLICT);
271	        }
272	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
273	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing ->
275	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
276	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
277	            .count();
278	        HttpHeaders headers = new HttpHeaders();
279	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
280	        owner.setNamesakeCount(namesakeCount);
281	        owner.setAddress(address);
282	        owner.setTelephone(telephone);
283	        owner.setEmail(email == null ? null : email.toLowerCase());
284	        if (owner.getRegistrationDate() == null) {
285	            owner.setRegistrationDate(LocalDate.now());
286	        }
287	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
288	        if (sharesHousehold && !householdMembers.isEmpty()) {
289	            String householdId = householdId(lastNameKey, addressKey);
290	            owner.setHouseholdId(householdId);
291	            for (Owner member : householdMembers) {
